{"explanation":"Put four copies of a right triangle with legs a and b inside a square with side a + b. In the first layout, the triangles sit in the corners. The empty space in the middle is a tilted square with side c, so its area is c². Now slide the same four triangles around, without turning them, so they form two rectangles. The empty space is now two squares with areas a² and b². The big square and the four triangles never changed, so the empty area must be the same in both layouts: c² = a² + b². Click the button or move the slider to watch the triangles slide. Change the a slider to try other right triangles: the areas still match.","manimCode":"const S = 5, X0 = -6, Y0 = -2.5;
const P = (u, v) => [X0 + u, Y0 + v, 0];
let a = 2;
const tr = new ValueTracker(0);

function baseTris(a) {
  const b = S - a;
  return [
    [[0,0],[a,0],[0,b]],
    [[S,0],[S,a],[a,0]],
    [[S,S],[b,S],[S,a]],
    [[0,S],[0,b],[b,S]]
  ];
}
function offsets(a) {
  const b = S - a;
  return [[0,a],[0,0],[-b,0],[a,-b]];
}

// Empty regions (drawn beneath triangles)
const cSq = new Polygon({ vertices: [P(0,0),P(1,0),P(1,1)], color: YELLOW });
cSq.setFill(YELLOW, 0.5);
const aSq = new Polygon({ vertices: [P(0,0),P(1,0),P(1,1)], color: RED });
aSq.setFill(RED, 0.5);
const bSq = new Polygon({ vertices: [P(0,0),P(1,0),P(1,1)], color: ORANGE });
bSq.setFill(ORANGE, 0.5);

const outer = new Square({ sideLength: S, color: WHITE });
outer.moveTo(P(S/2, S/2));

const cols = [BLUE_D, TEAL_D, GREEN_D, PURPLE];
const tris = cols.map(c => {
  const p = new Polygon({ vertices: [P(0,0),P(1,0),P(0,1)], color: WHITE });
  p.setFill(c, 0.9);
  p.setStrokeWidth(2);
  return p;
});

const cLab = new MathTex({ latex: 'c^2', color: WHITE });
const aLab = new MathTex({ latex: 'a^2', color: WHITE });
const bLab = new MathTex({ latex: 'b^2', color: WHITE });
const aSide = new MathTex({ latex: 'a', color: GRAY_A });
const bSide = new MathTex({ latex: 'b', color: GRAY_A });
for (const m of [cLab, aLab, bLab, aSide, bSide]) await m.waitForRender();

function update() {
  const t = tr.getValue();
  const b = S - a;
  const base = baseTris(a), off = offsets(a);
  tris.forEach((tri, i) => {
    tri.setVertices(base[i].map(([u, v]) => P(u + t * off[i][0], v + t * off[i][1])));
  });
  cSq.setVertices([P(a,0), P(S,a), P(b,S), P(0,b)]);
  aSq.setVertices([P(0,0), P(a,0), P(a,a), P(0,a)]);
  bSq.setVertices([P(a,a), P(S,a), P(S,S), P(a,S)]);
  cSq.setFillOpacity(0.5 * (1 - t)); cSq.setOpacity(1 - t);
  aSq.setFillOpacity(0.5 * t); aSq.setOpacity(t);
  bSq.setFillOpacity(0.5 * t); bSq.setOpacity(t);
  cLab.moveTo(P(S/2, S/2)); cLab.setOpacity(1 - t);
  aLab.moveTo(P(a/2, a/2)); aLab.setOpacity(t);
  bLab.moveTo(P(a + b/2, a + b/2)); bLab.setOpacity(t);
  aSide.moveTo(P(a/2, -0.35));
  bSide.moveTo(P(a + b/2, -0.35));
}
update();

const title = new Text({ text: 'Rearrangement proof', color: WHITE, fontSize: 30 });
title.moveTo([3.3, 3.2, 0]);
const eq1 = new MathTex({ latex: '(a+b)^2 = c^2 + 4\\cdot\\tfrac12 ab', color: YELLOW });
const eq2 = new MathTex({ latex: '(a+b)^2 = a^2 + b^2 + 4\\cdot\\tfrac12 ab', color: ORANGE });
const eq3 = new MathTex({ latex: '\\Rightarrow\\; a^2 + b^2 = c^2', color: GREEN });
for (const m of [eq1, eq2, eq3]) await m.waitForRender();
eq1.scale(0.7); eq2.scale(0.7); eq3.scale(0.9);
eq1.moveTo([3.3, 2.2, 0]);
eq2.moveTo([3.3, 1.4, 0]);
eq3.moveTo([3.3, 0.5, 0]);

scene.add(cSq, aSq, bSq, outer);
await scene.play(new Create(outer));
await scene.play(new AnimationGroup(tris.map(tr2 => new DrawBorderThenFill(tr2))));
scene.add(cLab, aLab, bLab, aSide, bSide);
outer.addUpdater(() => update());
await scene.play(new Write(title));
await scene.play(new Write(eq1));
await scene.wait(0.5);
await scene.play(tr.animateTo(1));
await scene.play(new Write(eq2));
await scene.play(new Write(eq3));

const controls = new Controls(scene, { position: 'bottom-right' });
controls.addButton({ label: 'Rearrange ↔', onClick: () => {
  scene.play(tr.animateTo(tr.getValue() < 0.5 ? 1 : 0));
}});
controls.addSlider({ label: 'Rearrange (t)', min: 0, max: 1, value: 1, step: 0.01, onChange: (v) => { tr.setValue(v); } });
controls.addSlider({ label: 'Leg a (b = 5 − a)', min: 0.8, max: 4.2, value: 2, step: 0.1, onChange: (v) => { a = v; } });

await scene.wait(999999);"}

